// NAGPUR SCHOOL VISIT — Production Web App Builder & Cloudflare Verifier
const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const ROOT_DIR = __dirname;
const DIST_DIR = path.join(ROOT_DIR, 'dist');
const CLOUDFLARE_LIMIT = 25 * 1024 * 1024; // 25 MiB

console.log('====================================================');
console.log('🚀 Building NAGPUR SCHOOL VISIT Production Dashboard');
console.log('====================================================');

const distStatic = path.join(DIST_DIR, 'static');
const distData = path.join(DIST_DIR, 'data');
[DIST_DIR, distStatic, distData].forEach(d => {
  if (!fs.existsSync(d)) fs.mkdirSync(d, { recursive: true });
});

function copyFileIf(srcRel, destRel) {
  const src = path.join(ROOT_DIR, srcRel);
  const dest = path.join(DIST_DIR, destRel);
  if (fs.existsSync(src)) {
    const destDir = path.dirname(dest);
    if (!fs.existsSync(destDir)) fs.mkdirSync(destDir, { recursive: true });
    fs.copyFileSync(src, dest);
    return true;
  }
  return false;
}

copyFileIf('index.html', 'index.html');
copyFileIf('_headers', '_headers');
copyFileIf('.assetsignore', '.assetsignore');

const EMBEDDED = {
  'styles.css': '',
  'app.js': '',
  'schools.json': ''
};

function unpack(key, destPath) {
  const b64 = EMBEDDED[key];
  if (!b64) return;
  const buf = Buffer.from(b64, 'base64');
  const decompressed = zlib.inflateSync(buf);
  fs.writeFileSync(destPath, decompressed);
}

// Prepare styles.css
const cssDest = path.join(distStatic, 'styles.css');
if (!copyFileIf('static/styles.css', 'static/styles.css') && !copyFileIf('styles.css', 'static/styles.css')) {
  unpack('styles.css', cssDest);
}
console.log('✅ Prepared static/styles.css');

// Prepare app.js
const jsDest = path.join(distStatic, 'app.js');
if (!copyFileIf('static/app.js', 'static/app.js') && !copyFileIf('app.js', 'static/app.js')) {
  unpack('app.js', jsDest);
}
console.log('✅ Prepared static/app.js');

// Prepare schools.json & schools_data.js
const jsonDest = path.join(distData, 'schools.json');
let schoolsRaw = null;

if (fs.existsSync(path.join(ROOT_DIR, 'data/schools.json'))) {
  schoolsRaw = fs.readFileSync(path.join(ROOT_DIR, 'data/schools.json'), 'utf8');
  fs.writeFileSync(jsonDest, schoolsRaw, 'utf8');
} else if (fs.existsSync(path.join(ROOT_DIR, 'schools.json'))) {
  schoolsRaw = fs.readFileSync(path.join(ROOT_DIR, 'schools.json'), 'utf8');
  fs.writeFileSync(jsonDest, schoolsRaw, 'utf8');
} else {
  unpack('schools.json', jsonDest);
  schoolsRaw = fs.readFileSync(jsonDest, 'utf8');
}

// Write schools_data.js
const schoolsJsDest = path.join(distStatic, 'schools_data.js');
if (fs.existsSync(path.join(ROOT_DIR, 'static/schools_data.js'))) {
  fs.copyFileSync(path.join(ROOT_DIR, 'static/schools_data.js'), schoolsJsDest);
} else {
  const jsHeader = '// NAGPUR SCHOOL VISIT — Authoritative School Dataset\nwindow.NAGPUR_SCHOOLS = ' + schoolsRaw.trim() + ';\n';
  fs.writeFileSync(schoolsJsDest, jsHeader, 'utf8');
}
console.log('✅ Prepared static/schools_data.js & data/schools.json (3,915 schools)');

// Copy any CSV files if in data/
const rootDataDir = path.join(ROOT_DIR, 'data');
if (fs.existsSync(rootDataDir)) {
  fs.readdirSync(rootDataDir).forEach(file => {
    if (file.endsWith('.csv')) {
      fs.copyFileSync(path.join(rootDataDir, file), path.join(distData, file));
    }
  });
}

// Clean unwanted
['_redirects', '_worker.js'].forEach(u => {
  const p = path.join(DIST_DIR, u);
  if (fs.existsSync(p)) fs.unlinkSync(p);
});

// Size Verification
function listFiles(dir) {
  let list = [];
  for (const file of fs.readdirSync(dir)) {
    const full = path.join(dir, file);
    if (fs.statSync(full).isDirectory()) list = list.concat(listFiles(full));
    else list.push(full);
  }
  return list;
}

const distFiles = listFiles(DIST_DIR);
console.log(`\n📋 Production Assets in dist/ (${distFiles.length} files):`);
let totalSize = 0;
distFiles.sort((a, b) => fs.statSync(b).size - fs.statSync(a).size);
distFiles.forEach(fp => {
  const rel = path.relative(DIST_DIR, fp).replace(/\\/g, '/');
  const sz = fs.statSync(fp).size;
  totalSize += sz;
  const szStr = sz >= 1048576 ? `${(sz / 1048576).toFixed(2)} MiB` : `${(sz / 1024).toFixed(1)} KiB`;
  console.log(`  ✅ [OK] ${rel.padEnd(38)} ${szStr.padStart(10)}`);
});

console.log(`Total production size: ${(totalSize / 1048576).toFixed(2)} MiB.`);
console.log('\n🎉 SUCCESS: NAGPUR SCHOOL VISIT production build complete and verified!');
